use crate::capture_model::{AxAppTree,AxNode}; use crate::capture_validate::{Line,UNKNOWN_SPEAKER};
const TEXT:&str="AXStaticText"; const GROUP:&str="AXGroup"; const MAX_NODES:usize=2000;
pub trait CaptionReader: Send+Sync { fn platform(&self)->&'static str; fn bundle_id(&self)->&'static str; fn read(&self,app:&AxAppTree)->Option<Vec<Line>>; }
pub struct ZoomReader; pub struct TeamsReader;
pub fn all_readers()->Vec<Box<dyn CaptionReader>>{vec![Box::new(ZoomReader),Box::new(TeamsReader)]}
fn val(n:&AxNode)->Option<&str>{n.value.as_deref().map(str::trim).filter(|t|!t.is_empty())}
fn texts<'a>(n:&'a AxNode,d:usize,max:usize,b:&mut usize,o:&mut Vec<&'a str>){if *b==0{return} *b-=1; if n.role==TEXT{if let Some(t)=val(n){o.push(t)}} if d>=max{return} for c in &n.children{texts(c,d+1,max,b,o)}}
fn split(t:&str)->Line{if let Some((s,b))=t.split_once('\n'){let(s,b)=(s.trim(),b.trim());if !s.is_empty()&&!b.is_empty(){return(s.into(),b.into())}}(UNKNOWN_SPEAKER.into(),t.into())}
impl CaptionReader for ZoomReader{fn platform(&self)->&'static str{"zoom"}fn bundle_id(&self)->&'static str{"us.zoom.xos"}fn read(&self,a:&AxAppTree)->Option<Vec<Line>>{let w=a.windows.iter().find(|w|w.title.as_deref().is_some_and(|t|t.to_lowercase().contains("caption"))).or_else(||a.windows.iter().find(|w|w.title.as_deref().is_some_and(|t|t.contains("字幕"))))?;let mut v=Vec::new();let mut b=MAX_NODES;texts(w,0,12,&mut b,&mut v);Some(v.into_iter().map(split).collect())}}
impl CaptionReader for TeamsReader{fn platform(&self)->&'static str{"teams"}fn bundle_id(&self)->&'static str{"com.microsoft.teams2"}fn read(&self,a:&AxAppTree)->Option<Vec<Line>>{let mut b=MAX_NODES;let p=a.windows.iter().find_map(|w|panel(w,0,16,&mut b))?;let mut g=Vec::new();let mut b=MAX_NODES;groups(p,0,16,&mut b,&mut g);Some(pair(&g))}}
fn panel<'a>(n:&'a AxNode,d:usize,max:usize,b:&mut usize)->Option<&'a AxNode>{if *b==0{return None} *b-=1;if n.role==GROUP&&n.description.as_deref().is_some_and(|d|d.to_lowercase().contains("live caption")){return Some(n)}if d>=max{return None}n.children.iter().find_map(|c|panel(c,d+1,max,b))}
fn groups(n:&AxNode,d:usize,max:usize,b:&mut usize,out:&mut Vec<Vec<String>>){if d>=max{return}let mut mine=None;for c in &n.children{if *b==0{return} *b-=1;if c.role==TEXT{if let Some(t)=val(c){let i=*mine.get_or_insert_with(||{out.push(Vec::new());out.len()-1});out[i].push(t.into())}}groups(c,d+1,max,b,out)}}
pub fn pair_caption_rows(groups:&[Vec<String>])->Vec<Line>{let ne:Vec<&Vec<String>>=groups.iter().filter(|g|!g.is_empty()).collect();if ne.is_empty(){return Vec::new()}if !(ne.len()>1||ne[0].len()==2){return ne[0].chunks(2).filter(|c|c.len()==2).map(|c|(c[0].clone(),c[1].clone())).collect()}let mut o=Vec::new();let mut last:Option<&str>=None;for g in ne{if g.len()==1{if let Some(s)=last{o.push((s.into(),g[0].clone()))}continue}o.push((g[0].clone(),g[1..].join(" ")));last=Some(g[0].as_str())}o}
pub use pair_caption_rows as pair;
#[cfg(test)] mod tests{use super::*;use crate::capture_delta::{CaptionDelta,DeltaState};use crate::capture_validate::clean_lines;use serde_json::Value;
 const F:&[(&str,&str)]=&[("zoom-basic",include_str!("../tests/fixtures/captions/zoom-basic.json")),("zoom-ja",include_str!("../tests/fixtures/captions/zoom-ja.json")),("zoom-no-panel",include_str!("../tests/fixtures/captions/zoom-no-panel.json")),("teams-structured",include_str!("../tests/fixtures/captions/teams-structured.json")),("teams-flat",include_str!("../tests/fixtures/captions/teams-flat.json")),("teams-no-panel",include_str!("../tests/fixtures/captions/teams-no-panel.json"))];
 fn r(n:&str)->Box<dyn CaptionReader>{all_readers().into_iter().find(|r|r.platform()==n).unwrap()}
 fn rows(v:&Value)->Option<Vec<Line>>{v.as_array().map(|a|a.iter().map(|p|(p[0].as_str().unwrap().into(),p[1].as_str().unwrap().into())).collect())}
 #[test]fn fixtures(){for(n,s)in F{let fx:Value=serde_json::from_str(s).unwrap();let app:AxAppTree=serde_json::from_value(fx["app"].clone()).unwrap();let raw=r(fx["reader"].as_str().unwrap()).read(&app);assert_eq!(raw,rows(&fx["raw"]),"{n} raw");assert_eq!(raw.map(clean_lines),rows(&fx["clean"]),"{n} clean")}}
 #[test]fn growth(){let fx:Value=serde_json::from_str(include_str!("../tests/fixtures/captions/teams-growth-sequence.json")).unwrap();let r=r("teams");let mut st=DeltaState::new();let mut k=Vec::new();let mut t:Vec<(u64,String,String)>=Vec::new();for f in fx["frames"].as_array().unwrap(){let app:AxAppTree=serde_json::from_value(f.clone()).unwrap();for d in st.ingest(&clean_lines(r.read(&app).unwrap())){match d{CaptionDelta::Append{row,speaker,text}=>{k.push("append");t.push((row,speaker,text))}CaptionDelta::Replace{row,new_text,..}=>{k.push("replace");t.iter_mut().find(|x|x.0==row).unwrap().2=new_text}CaptionDelta::Closed{..}=>k.push("closed")}}}let want:Vec<&str>=fx["deltaKinds"].as_array().unwrap().iter().map(|x|x.as_str().unwrap()).collect();assert_eq!(k,want);let got:Vec<Line>=t.into_iter().map(|(_,s,t)|(s,t)).collect();assert_eq!(Some(got),rows(&fx["finalRows"]))}
 #[test]fn pair() {assert!(pair_caption_rows(&[]).is_empty());assert_eq!(pair_caption_rows(&[vec!["A".into(),"x".into(),"y".into(),"z".into()]]),vec![("A".into(),"x".into()),("y".into(),"z".into())])}
 #[test]fn bounded(){let mut d=AxNode{role:TEXT.into(),value:Some("Tanaka\nEnd.".into()),..Default::default()};for _ in 0..5000{d=AxNode{role:GROUP.into(),children:vec![d],..Default::default()}}let a=AxAppTree{bundle_id:"us.zoom.xos".into(),windows:vec![AxNode{role:"AXWindow".into(),title:Some("Captions".into()),children:vec![d],..Default::default()}]};assert_eq!(r("zoom").read(&a),Some(vec![]))}}
